#!/bin/sh

# The image filesystem can be read-only, so the generated config lives in /tmp
PHP_RUNTIME_CONF_DIR="/tmp/php/conf.d"
mkdir -p "${PHP_RUNTIME_CONF_DIR}"
export PHP_INI_SCAN_DIR="${PHP_INI_DIR}/conf.d:${PHP_RUNTIME_CONF_DIR}"

cat <<EOT > "${PHP_RUNTIME_CONF_DIR}/10-upload-limits.ini"
# Generated by configure-php.sh

upload_max_filesize = ${UPLOAD_LIMIT}
post_max_size = ${UPLOAD_LIMIT}
EOT
